#pragma once
#include <JuceHeader.h>
#include <cmath>
#include "FXTokens.h"
namespace fx{class FXLookAndFeel:public juce::LookAndFeel_V4{public:explicit FXLookAndFeel(juce::Colour a):accentColour(a){setColour(juce::Slider::textBoxTextColourId,col::textPrimary);setColour(juce::Slider::textBoxOutlineColourId,juce::Colours::transparentBlack);setColour(juce::Slider::rotarySliderFillColourId,a);setColour(juce::Slider::rotarySliderOutlineColourId,col::border);setColour(juce::ComboBox::backgroundColourId,col::surfPrimary.brighter(.05f));setColour(juce::ComboBox::textColourId,col::textPrimary);setColour(juce::ComboBox::outlineColourId,col::border);setColour(juce::ComboBox::arrowColourId,a);setColour(juce::PopupMenu::backgroundColourId,col::surfSecondary);setColour(juce::PopupMenu::textColourId,col::textPrimary);setColour(juce::PopupMenu::highlightedBackgroundColourId,a.withAlpha(.25f));setColour(juce::PopupMenu::highlightedTextColourId,col::textPrimary);}juce::Colour getAccent()const{return accentColour;}void drawRotarySlider(juce::Graphics&g,int x,int y,int w,int h,float p,float s,float e,juce::Slider&)override{auto r=juce::Rectangle<float>((float)x,(float)y,(float)w,(float)h).reduced(6);auto rad=juce::jmin(r.getWidth(),r.getHeight())*.5f,cx=r.getCentreX(),cy=r.getCentreY(),a=s+p*(e-s);juce::Path t;t.addCentredArc(cx,cy,rad,rad,0,s,e,true);g.setColour(col::surfTertiary);g.strokePath(t,juce::PathStrokeType((float)dim::knobRing,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));if(p>.001f){juce::Path q;q.addCentredArc(cx,cy,rad,rad,0,s,a,true);g.setColour(accentColour);g.strokePath(q,juce::PathStrokeType((float)dim::knobRing,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));}float br=rad*.68f;g.setColour(col::surfTertiary);g.fillEllipse(cx-br,cy-br,br*2,br*2);g.setColour(col::border);g.drawEllipse(cx-br,cy-br,br*2,br*2,1);juce::ColourGradient shadow(juce::Colours::black.withAlpha(.25f),cx,cy-br,juce::Colours::transparentBlack,cx,cy+br,false);g.setGradientFill(shadow);g.fillEllipse(cx-br,cy-br,br*2,br*2);auto aa=a-juce::MathConstants<float>::halfPi;g.setColour(col::textPrimary);g.drawLine(cx+std::cos(aa)*br*.35f,cy+std::sin(aa)*br*.35f,cx+std::cos(aa)*br*.85f,cy+std::sin(aa)*br*.85f,2);g.setColour(accentColour.withAlpha(.6f));g.fillEllipse(cx-2.5f,cy-2.5f,5,5);}void drawComboBox(juce::Graphics&g,int w,int h,bool,int,int,int,int,juce::ComboBox&b)override{auto r=juce::Rectangle<float>(0,0,(float)w,(float)h);g.setColour(b.findColour(juce::ComboBox::backgroundColourId));g.fillRoundedRectangle(r,(float)dim::btnR);g.setColour(b.findColour(juce::ComboBox::outlineColourId));g.drawRoundedRectangle(r.reduced(.5f),(float)dim::btnR,1);juce::Path p;float cx=(float)w-14,cy=(float)h*.5f;p.addTriangle(cx-3.5f,cy-2,cx+3.5f,cy-2,cx,cy+3);g.setColour(b.findColour(juce::ComboBox::arrowColourId));g.fillPath(p);}void drawButtonBackground(juce::Graphics&g,juce::Button&b,const juce::Colour&c,bool o,bool d)override{auto r=b.getLocalBounds().toFloat().reduced(1);auto f=c;if(b.getToggleState())f=accentColour;else if(d)f=f.brighter(.12f);else if(o)f=f.brighter(.06f);g.setColour(f);g.fillRoundedRectangle(r,(float)dim::btnR);g.setColour(col::border);g.drawRoundedRectangle(r,(float)dim::btnR,1);}void drawButtonText(juce::Graphics&g,juce::TextButton&b,bool,bool)override{g.setColour(b.getToggleState()?col::bg:col::textPrimary);g.setFont(juce::Font(juce::FontOptions{}.withHeight(font::label)));g.drawText(b.getButtonText(),b.getLocalBounds(),juce::Justification::centred);}void drawLabel(juce::Graphics&g,juce::Label&l)override{g.fillAll(l.findColour(juce::Label::backgroundColourId));g.setColour(l.findColour(juce::Label::textColourId));g.setFont(l.getFont());g.drawText(l.getText(),l.getLocalBounds(),l.getJustificationType());}void drawLinearSlider(juce::Graphics&g,int x,int y,int w,int h,float p,float,float,juce::Slider::SliderStyle,juce::Slider&)override{auto b=juce::Rectangle<float>((float)x,(float)y,(float)w,(float)h);auto yy=b.getCentreY();g.setColour(col::surfTertiary);g.fillRoundedRectangle(b.getX(),yy-2,b.getWidth(),4,2);auto fw=p-b.getX();if(fw>0){g.setColour(accentColour);g.fillRoundedRectangle(b.getX(),yy-2,fw,4,2);}g.setColour(col::textPrimary);g.fillEllipse(p-6,yy-6,12,12);g.setColour(accentColour);g.fillEllipse(p-4,yy-4,8,8);}private:juce::Colour accentColour;};}
